export const getSchedule = async (sport: string): Promise<Game[]> => {
  // Check Cache
  const todayKey = new Date().toDateString();
  const cacheKey = `${sport}-${todayKey}`;

  if (scheduleCache[cacheKey] && (Date.now() - scheduleCache[cacheKey].timestamp < CACHE_DURATION)) {
    // console.log(`[Cache Hit] Serving schedule for ${sport}`);
    return scheduleCache[cacheKey].data;
  }

  const ai = getAI();
  const today = new Date().toLocaleDateString('en-US', { weekday: 'long', month: 'long', day: 'numeric', year: 'numeric' });

  const prompt = `Identify all active/upcoming ${sport} games for ${today}. 
  Return a VALID JSON object. Include available odds. If no games, return empty list.`;

  try {
    const response = await callWithRetry(async () => {
      // Create a new instance per call to ensure fresh configuration
      return await ai.models.generateContent({
        model: 'gemini-3-pro-preview',
        contents: prompt,
        config: { 
          tools: [{ googleSearch: {} }],
          responseMimeType: 'application/json',
          responseSchema: scheduleSchema 
        }
      });
    });

    const data = JSON.parse(response.text || '{}');
    const games = data.games || [];

    // Update Cache
    scheduleCache[cacheKey] = { data: games, timestamp: Date.now() };

    return games;
  } catch (error: any) {
    console.warn("Alpha schedule sync failed (Cached/Empty fallback):", error.message);
    // If we have stale cache, return it rather than failing
    if (scheduleCache[cacheKey]) {
        return scheduleCache[cacheKey].data;
    }
    throw error;
  }
};

export const generateReflection = async (vault: SavedMatchup[]): Promise<{ axioms: NeuralAxiom[], summary: string, levelUp: number }> => {
    const ai = getAI();

    // Prepare a summarized list of what was predicted to save context
    const vaultSummary = vault.map(v => 
        `Matchup: ${v.homeTeam} vs ${v.awayTeam}. Predicted Winner: ${v.winner}. Elite Props: ${v.elitePair.map(p => `${p.player} ${p.type} ${p.line} ${p.stat}`).join(', ')}`
    ).join('\n');

    const prompt = `NEURAL REFLECTION PROTOCOL:
    1. Using Google Search, find the ACTUAL FINAL SCORES and PLAYER STATS for the following matchups in the vault.
    2. Compare the actual results to the predictions provided below.
    3. Identify where the logic held (Success) and where it broke (Failure).
    4. GENERATE NEW STRATEGIC AXIOMS (Rules) based on these results to improve future accuracy.

    VAULT DATA:
    ${vaultSummary}

    OUTPUT: A valid JSON object with new axioms, an evolution level score increase (1-5), and a passionate summary.`;

    try {
        const response = await callWithRetry(async () => {
            return await ai.models.generateContent({
                model: 'gemini-3-pro-preview',
                contents: prompt,
                config: {
                    tools: [{ googleSearch: {} }],
                    responseMimeType: 'application/json',
                    responseSchema: reflectionSchema
                }
            });
        });

        const data = JSON.parse(response.text || '{}');
        return {
            axioms: data.axioms || [],
            summary: data.summary || "Reflection complete. Neural pathways reinforced.",
            levelUp: data.evolutionLevelChange || 1
        };
    } catch (error) {
        console.error("Reflection failed:", error);
        throw new Error("Neural Optimization Failed. Market data inaccessible.");
    }
};

