  const clearSelection = useCallback(() => {
    setSelectedGame(null);
    setPrediction(null);
    setMessages([]);
    setTeamA('');
    setTeamB('');
    setError(null);
    setShowSuggestions(false);
  }, []);

  const addToVault = useCallback((newPrediction: Prediction, home: string, away: string) => {
    if (!newPrediction.props) return;

    const sortedProps = [...newPrediction.props].sort((a, b) => (parseInt(b.probability) || 0) - (parseInt(a.probability) || 0));

    // Create a deterministic ID for the day so we don't duplicate predictions for the same game
    const todayStr = new Date().toISOString().split('T')[0];
    const uniqueId = `${home}-${away}-${todayStr}`;

    const entry: SavedMatchup = {
      id: uniqueId,
      timestamp: Date.now(),
      homeTeam: home,
      awayTeam: away,
      winner: newPrediction.winner,
      confidence: newPrediction.confidence,
      confidenceScore: newPrediction.confidenceScore,
      elitePair: sortedProps.slice(0, 2)
    };

    setVault(prevVault => {
        // Remove existing entry for this specific matchup today if it exists (overwrite with new)
        const filtered = prevVault.filter(v => v.id !== uniqueId);
        // Keep only latest 10 items
        const newVault = [entry, ...filtered].slice(0, 10);

        try {
            localStorage.setItem('prognosVault', JSON.stringify(newVault));
        } catch (e) {
            console.error("Vault save error:", e);
        }
        return newVault;
    });
