                                    />
                                    <button type="submit" className="absolute right-5 top-5 bg-amber-500 text-black p-4 rounded-2xl hover:bg-amber-400 shadow-lg transition-transform active:scale-95">
                                        <SearchIcon className="w-5 h-5" />
