export const GameSchedule: React.FC<GameScheduleProps> = memo(({ sport, selectedGame, onSelectGame, oddsFormat = 'American' }) => {
  const [games, setGames] = useState<Game[]>([]);
  const [isLoading, setIsLoading] = useState<boolean>(false);
  const [isRefreshing, setIsRefreshing] = useState<boolean>(false);
  const [error, setError] = useState<string | null>(null);
  const [isQuotaError, setIsQuotaError] = useState<boolean>(false);
  const [loadMsgIdx, setLoadMsgIdx] = useState(0);
  const [lastUpdated, setLastUpdated] = useState<Date>(new Date());
  const [retryCooldown, setRetryCooldown] = useState<number>(0);

  const fetchGames = useCallback(async (quiet = false) => {
    if (retryCooldown > 0) return;

    if (!quiet) setIsLoading(true);
    else setIsRefreshing(true);

    setError(null);
    setIsQuotaError(false);
    try {
      const fetchedGames = await getSchedule(sport);
      if (fetchedGames && fetchedGames.length > 0) {
        setGames(fetchedGames);
        setLastUpdated(new Date());
      } else if (!quiet) {
        setError(`No active ${sport} markets found in current data stream.`);
      }
    } catch (err: any) {
      const isQuota = err.status === 429 || JSON.stringify(err).includes("429") || JSON.stringify(err).includes("RESOURCE_EXHAUSTED");
      if (isQuota) {
        setIsQuotaError(true);
        setError("Neural Bandwidth Restricted: Quota Limit Reached. Engine is cooling down.");
        setRetryCooldown(45); // Cooldown for 45s
      } else if (!quiet) {
        setError('Satellite link lost. Engine cannot reach market data.');
      }
    } finally {
      setIsLoading(false);
      setIsRefreshing(false);
    }
  }, [sport, retryCooldown]);

  useEffect(() => {
    if (retryCooldown > 0) {
      const timer = setInterval(() => setRetryCooldown(prev => prev - 1), 1000);
      return () => clearInterval(timer);
    }
  }, [retryCooldown]);

  useEffect(() => { fetchGames(); }, [sport]);

  useEffect(() => {
    // Increased polling interval to 2.5 mins to reduce API load
    const pollInterval = setInterval(() => fetchGames(true), 150000);
    return () => clearInterval(pollInterval);
  }, [fetchGames]);

  useEffect(() => {
    if ((isLoading || isRefreshing) && games.length === 0) {
      const timer = setInterval(() => {
        setLoadMsgIdx((prev) => (prev + 1) % LOAD_SUB_MESSAGES.length);
      }, 1200);
      return () => clearInterval(timer);
    }
  }, [isLoading, isRefreshing, games.length]);

  const groupedGames = useMemo(() => {
    const today = new Date().toLocaleDateString('en-US', { month: 'long', day: 'numeric', year: 'numeric' });

    const groups: Record<string, Game[]> = {};
    games.forEach(game => {
      let dateKey = game.date || today;
      if (!groups[dateKey]) groups[dateKey] = [];
      groups[dateKey].push(game);
    });

    return Object.entries(groups).sort((a, b) => new Date(a[0]).getTime() - new Date(b[0]).getTime());
  }, [games]);

  if (isLoading && games.length === 0) {
    return (
      <div className="py-32 flex flex-col items-center justify-center space-y-8 animate-pulse">
        <div className="relative w-20 h-20">
          <div className="absolute inset-0 border-4 border-amber-500/10 rounded-full"></div>
          <div className="absolute inset-0 border-4 border-t-amber-500 rounded-full animate-spin"></div>
          <div className="absolute inset-4 bg-amber-500/5 rounded-full blur-xl"></div>
        </div>
        <div className="text-center space-y-2">
          <div className="text-zinc-600 font-black uppercase text-[10px] tracking-[0.5em] mb-2">Deep Sync Active</div>
          <div className="text-amber-500 font-black uppercase text-xs tracking-[0.2em] animate-pulse">
            {LOAD_SUB_MESSAGES[loadMsgIdx]}
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-12 w-full animate-fade-in">
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center px-4 gap-4">
          <div className="flex items-center gap-3">
              <div className={`w-1.5 h-1.5 rounded-full animate-pulse shadow-[0_0_8px_rgba(245,158,11,0.8)] ${isQuotaError ? 'bg-orange-500' : 'bg-amber-500'}`}></div>
              <h3 className="text-[11px] font-black text-zinc-500 uppercase tracking-[0.4em]">Tactical Feed: {sport}</h3>
          </div>
          <div className="flex items-center gap-4">
              <span className="text-[8px] font-black text-zinc-700 uppercase tracking-widest bg-zinc-950 px-3 py-1 rounded-full border border-zinc-900">
                Last Sync: {lastUpdated.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' })}
              </span>
              <button 
                onClick={() => fetchGames(true)} 
                disabled={isRefreshing || retryCooldown > 0} 
                className={`text-[9px] font-black uppercase tracking-widest transition-all px-4 py-1.5 rounded-lg border flex items-center gap-2 ${
                  isRefreshing || retryCooldown > 0
                    ? 'text-amber-500 border-amber-500/50 bg-amber-500/10 cursor-not-allowed' 
                    : 'text-zinc-500 border-zinc-800 hover:text-amber-500 hover:border-amber-500/50 bg-black/40'
                }`}
              >
                  <LogoIcon className={`w-3 h-3 ${isRefreshing ? 'animate-spin' : ''}`} />
                  {isRefreshing ? 'Deep Scanning...' : retryCooldown > 0 ? `Cooling: ${retryCooldown}s` : 'Refresh Signal'}
              </button>
          </div>
      </div>

      {error && (
        <div className={`mx-4 p-8 rounded-[2.5rem] text-center border-2 border-dashed transition-all ${
          isQuotaError ? 'bg-orange-950/10 border-orange-500/40' : 'bg-zinc-950/80 border-zinc-900'
        }`}>
            <span className={`text-[10px] font-black uppercase tracking-[0.3em] block mb-2 ${isQuotaError ? 'text-orange-500' : 'text-zinc-600'}`}>
              {isQuotaError ? 'Neural Overload (Rate Limit)' : 'Feed Interruption'}
            </span>
            <p className="text-xs text-zinc-400 font-medium italic mb-4">{error}</p>
            {retryCooldown > 0 && (
                <div className="w-full max-w-xs mx-auto h-1 bg-zinc-900 rounded-full overflow-hidden mb-4">
                    <div className="h-full bg-orange-500 transition-all duration-1000" style={{ width: `${(retryCooldown / 45) * 100}%` }}></div>
                </div>
            )}
        </div>
      )}

      <div className="space-y-16">
        {groupedGames.map(([date, dateGames]) => {
          const isToday = new Date(date).toDateString() === new Date().toDateString();
          return (
            <div key={date} className="space-y-6">
              <div className="flex items-center gap-4 px-4">
                <div className="h-px flex-1 bg-gradient-to-r from-transparent via-zinc-800 to-zinc-800"></div>
                <div className="flex flex-col items-center">
                  <span className={`text-[10px] font-black uppercase tracking-[0.4em] ${isToday ? 'text-amber-500' : 'text-zinc-600'}`}>
                    {isToday ? 'Live Markets (Today)' : date}
                  </span>
                  <span className="text-[8px] font-bold text-zinc-800 uppercase tracking-widest mt-1">{date}</span>
                </div>
                <div className="h-px flex-1 bg-gradient-to-l from-transparent via-zinc-800 to-zinc-800"></div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                {dateGames.map((game) => (
                  <GameCard 
                    key={game.id} 
                    game={game} 
                    isSelected={selectedGame?.id === game.id} 
                    onSelectGame={onSelectGame}
                    oddsFormat={oddsFormat} 
                  />
                ))}
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
});

