const NeuralRadarChart = memo(({ metrics }: { metrics: Prediction['calibrationMetrics'] }) => {
    if (!metrics) return null;

    // Map variance string to 0-100 score (Minimal risk = High score/stability)
    const varianceScore = 
        metrics.varianceRisk === 'Minimal' ? 95 :
        metrics.varianceRisk === 'Moderate' ? 70 :
        metrics.varianceRisk === 'High' ? 40 : 20;

    const data = [
        { label: 'STABILITY', value: metrics.rosterStability || 50 },
        { label: 'MARKET', value: metrics.marketAlignment || 50 },
        { label: 'CERTAINTY', value: metrics.situationalCertainty || 50 },
        { label: 'PREDICTABILITY', value: varianceScore },
    ];

    const size = 240;
    const center = size / 2;
    const radius = 80;
    const angleStep = (Math.PI * 2) / 4;

    const getCoordinates = (value: number, index: number) => {
        const angle = index * angleStep - Math.PI / 2; 
        const r = (value / 100) * radius;
        return {
            x: center + r * Math.cos(angle),
            y: center + r * Math.sin(angle)
        };
    };

    const polyPoints = data.map((d, i) => {
        const coords = getCoordinates(d.value, i);
        return `${coords.x},${coords.y}`;
    }).join(' ');

    const gridLevels = [25, 50, 75, 100];

    return (
        <div className="relative flex flex-col items-center justify-center p-6 bg-zinc-950/50 rounded-[2.5rem] border-2 border-zinc-900 tactical-outline">
            <div className="absolute top-6 left-6 flex items-center gap-2" aria-hidden="true">
                <div className="w-1.5 h-1.5 bg-amber-500 rounded-full animate-pulse"></div>
                <span className="text-[9px] font-black text-zinc-500 uppercase tracking-widest">Calibration Vector</span>
            </div>

            <svg width={size} height={size} className="overflow-visible" aria-hidden="true">
                {[0, 1, 2, 3].map(i => {
                    const coords = getCoordinates(100, i);
                    return (
                        <line 
                            key={`axis-${i}`} 
                            x1={center} y1={center} 
                            x2={coords.x} y2={coords.y} 
                            stroke="#3f3f46" strokeWidth="1" strokeDasharray="4 4" 
                        />
                    );
                })}

                {gridLevels.map((level, i) => {
                    const points = [0, 1, 2, 3].map(idx => {
                        const coords = getCoordinates(level, idx);
                        return `${coords.x},${coords.y}`;
                    }).join(' ');
                    return (
                        <polygon 
                            key={`grid-${i}`} 
                            points={points} 
                            fill="none" 
                            stroke="#27272a" 
                            strokeWidth="1" 
                        />
                    );
                })}

                <polygon 
                    points={polyPoints} 
                    fill="rgba(245, 158, 11, 0.15)" 
                    stroke="#f59e0b" 
                    strokeWidth="2" 
                    className="drop-shadow-[0_0_10px_rgba(245,158,11,0.5)]"
                />

                {data.map((d, i) => {
                    const coords = getCoordinates(d.value, i);
                    return (
                        <circle 
                            key={`point-${i}`} 
                            cx={coords.x} cy={coords.y} r="3" 
                            fill="#f59e0b" 
                            stroke="#000" strokeWidth="2"
                        />
                    );
                })}

                {data.map((d, i) => {
                    const coords = getCoordinates(120, i); 
                    return (
                        <text 
                            key={`label-${i}`} 
                            x={coords.x} y={coords.y} 
                            fill="#71717a" 
                            fontSize="8" 
                            fontWeight="900" 
                            textAnchor="middle" 
                            alignmentBaseline="middle"
                            className="uppercase tracking-widest"
                        >
                            {d.label}
                        </text>
                    );
                })}
            </svg>

            <div className="mt-2 flex gap-4" aria-hidden="true">
                <div className="flex flex-col items-center">
                    <span className="text-[8px] font-black text-zinc-600 uppercase">Load Index</span>
                    <span className="text-xs font-black text-white">{metrics.psychologicalLoadIndex || '--'}/100</span>
                </div>
            </div>
        </div>
    );
});

