export const getSchedule = async (sport: string): Promise<Game[]> => {
  // Check Cache
  const todayKey = new Date().toDateString();
  const cacheKey = `${sport}-${todayKey}`;

  if (scheduleCache[cacheKey] && (Date.now() - scheduleCache[cacheKey].timestamp < CACHE_DURATION)) {
    return scheduleCache[cacheKey].data;
  }

  const ai = getAI();
  const today = new Date().toLocaleDateString('en-US', { weekday: 'long', month: 'long', day: 'numeric', year: 'numeric' });

  const prompt = `Identify all active/upcoming ${sport} games for ${today}. 
  Return a VALID JSON object. Include available odds. If no games, return empty list.`;

  try {
    const response = await callWithRetry(async () => {
      // Create a new instance per call to ensure fresh configuration
      return await ai.models.generateContent({
        model: 'gemini-3-pro-preview',
        contents: prompt,
        config: { 
          tools: [{ googleSearch: {} }],
          responseMimeType: 'application/json',
          responseSchema: scheduleSchema 
        }
      });
    });

    const data = JSON.parse(response.text || '{}');
    const games = data.games || [];

    // Update Cache
    scheduleCache[cacheKey] = { data: games, timestamp: Date.now() };

    return games;
  } catch (error: any) {
    console.warn("Alpha schedule sync failed (Cached/Empty fallback):", error.message);
    if (scheduleCache[cacheKey]) {
        return scheduleCache[cacheKey].data;
    }
    throw error;
  }
};

export const generatePrediction = async (home: string, away: string, systemInstruction: string): Promise<Prediction> => {
    const ai = getAI();
    // Supernatural Logic: "Veto & Validate" Protocol + Protocol 80 (Sharp Action)
    const prompt = `
    ACTIVATE "SUPERNATURAL ACCURACY" PROTOCOL FOR ${home} vs ${away}.

    PHASE 1: THE VETO CHECK (CRITICAL)
    You MUST first perform a specific Google Search for:
    1. "${home} injury report today late scratch"
    2. "${away} injury report today late scratch"
    3. "Referee assignment ${home} vs ${away} tendencies"

    PHASE 2: PROTOCOL 80 (MARKET PSYCHOLOGY) - *NEW & CRITICAL*
    Perform a search for "Betting splits ${home} vs ${away} public vs sharp".
    - IDENTIFY REVERSE LINE MOVEMENT (RLM): If >65% of bets are on one side, but the line moved AGAINST them, that is Sharp Money.
    - TRAP DETECTION: If a top-tier team is playing a low-tier team and the spread is suspiciously small (e.g., -2.5), flag as a TRAP.
    - Populate 'syndicateIntel' and 'trapDetection' fields with this data.

    PHASE 3: THE SYNDICATE SIMULATION
    Simulate three distinct expert personas to derive the truth:
    A) THE QUANT: Pure efficiency metrics, pace, effective field goal %. No emotion.
    B) THE SHARP: Tracks "Smart Money". Values RLM and fading the public.
    C) THE SCOUT: Psychological factors (Scandals, Motivation, Revenge).

    PHASE 4: EXECUTION & QUANTUM AUDIT
    - Combine these into 'ensembleModel'.
    - If "Sharp" and "Quant" disagree, favor the "Sharp" (Vegas knows best).
    - Calculate 'entropyScore' (0-20=Lock, 80-100=Chaos).

    OUTPUT:
    Return a JSON response adhering strictly to the schema. 
    The 'analysis' field should read like a confidential intelligence briefing.
    `;

    return await callWithRetry(async () => {
        const response = await ai.models.generateContent({
            model: 'gemini-3-pro-preview',
            contents: prompt,
            config: {
                systemInstruction: systemInstruction,
                responseSchema: predictionSchema,
                responseMimeType: 'application/json',
                thinkingConfig: { thinkingBudget: 32768 },
                tools: [{ googleSearch: {} }]
            }
        });

        const cleanText = response.text?.replace(/```json\n?|```/g, '').trim();
        if (!cleanText) throw new Error("Received empty neural response signal.");

        return JSON.parse(cleanText);
    });
};

export const generateReflection = async (vault: SavedMatchup[]): Promise<{ axioms: NeuralAxiom[], summary: string, levelUp: number }> => {
    const ai = getAI();

    const vaultSummary = vault.map(v => 
        `Matchup: ${v.homeTeam} vs ${v.awayTeam}. Predicted Winner: ${v.winner}. Elite Props: ${v.elitePair.map(p => `${p.player} ${p.type} ${p.line} ${p.stat}`).join(', ')}`
    ).join('\n');

    const prompt = `NEURAL REFLECTION PROTOCOL:
    1. Using Google Search, find the ACTUAL FINAL SCORES and PLAYER STATS for the following matchups in the vault.
    2. Compare the actual results to the predictions provided below.
    3. Identify where the logic held (Success) and where it broke (Failure).
    4. GENERATE NEW STRATEGIC AXIOMS (Rules) based on these results to improve future accuracy.

    VAULT DATA:
    ${vaultSummary}

    OUTPUT: A valid JSON object with new axioms, an evolution level score increase (1-5), and a passionate summary.`;

    try {
        const response = await callWithRetry(async () => {
            return await ai.models.generateContent({
                model: 'gemini-3-pro-preview',
                contents: prompt,
                config: {
                    tools: [{ googleSearch: {} }],
                    responseMimeType: 'application/json',
                    responseSchema: reflectionSchema
                }
            });
        });

        const data = JSON.parse(response.text || '{}');
        return {
            axioms: data.axioms || [],
            summary: data.summary || "Reflection complete. Neural pathways reinforced.",
            levelUp: data.evolutionLevelChange || 1
        };
    } catch (error) {
        console.error("Reflection failed:", error);
        throw new Error("Neural Optimization Failed. Market data inaccessible.");
    }
};

export const analyzePickSlip = async (imageData: string, mimeType: string): Promise<Prediction> => {
    const ai = getAI();

    const prompt = `
    ANALYZE THIS BETTING SLIP IMAGE.

    1. EXTRACT all bets, teams, players, and lines visible.
    2. RUN "PROTOCOL 80" ANALYSIS on each leg of the slip.
       - Is this a "Public" bet or a "Sharp" bet?
       - Are there negative correlations?
    3. GENERATE A PREDICTION object based on the MAIN EVENT in the slip (or the first one if multiple).

    If the image is a parlay, set the 'analysis' field to a breakdown of the parlay's EV (Expected Value).
    Identify the Winner/Loser of the main matchup shown.

    Return VALID JSON matching the prediction schema.
    `;

    return await callWithRetry(async () => {
        const response = await ai.models.generateContent({
            model: 'gemini-3-pro-preview',
            contents: {
                parts: [
                    { inlineData: { data: imageData, mimeType: mimeType } },
                    { text: prompt }
                ]
            },
            config: {
                responseSchema: predictionSchema,
                responseMimeType: 'application/json',
                tools: [{ googleSearch: {} }] // Allow search to verify player status
            }
        });

        const cleanText = response.text?.replace(/```json\n?|```/g, '').trim();
        if (!cleanText) throw new Error("Slip analysis failed.");

        return JSON.parse(cleanText);
    });
};

