export const getSchedule = async (sport: string): Promise<Game[]> => {
  // Check Cache
  const todayKey = new Date().toDateString();
  const cacheKey = `${sport}-${todayKey}`;

  if (scheduleCache[cacheKey] && (Date.now() - scheduleCache[cacheKey].timestamp < CACHE_DURATION)) {
    return scheduleCache[cacheKey].data;
  }

  const ai = getAI();
  const today = new Date().toLocaleDateString('en-US', { weekday: 'long', month: 'long', day: 'numeric', year: 'numeric' });

  const prompt = `
  Perform a real-time data retrieval for active/upcoming ${sport} games on ${today}.

  ACTIONS:
  1. Search for the confirmed game schedule.
  2. CRITICAL: Search for the LATEST CONSENSUS BETTING ODDS (Spread, Moneyline, Total) from major sportsbooks.
  3. If a game is currently LIVE (in progress), fetch the real-time score and LIVE adjusted odds if available.

  RETURN FORMAT:
  Return a VALID JSON object matching the schema. 
  - Ensure 'status' is correct ('Scheduled', 'Live', 'Finished').
  - Populate 'odds' with the consensus numbers. Use 'Even' or '-' if unavailable.
  `;

  try {
    const response = await callWithRetry(async () => {
      // Create a new instance per call to ensure fresh configuration
      return await ai.models.generateContent({
        model: 'gemini-3-pro-preview',
        contents: prompt,
        config: { 
          tools: [{ googleSearch: {} }],
          responseMimeType: 'application/json',
          responseSchema: scheduleSchema 
        }
      });
    });

    const data = JSON.parse(response.text || '{}');
    const games = data.games || [];

    // Update Cache
    scheduleCache[cacheKey] = { data: games, timestamp: Date.now() };

    return games;
  } catch (error: any) {
    console.warn("Alpha schedule sync failed (Cached/Empty fallback):", error.message);
    if (scheduleCache[cacheKey]) {
        return scheduleCache[cacheKey].data;
    }
    throw error;
  }
};

